// UNIVERSAL FAN-OUT
if (items.length > 1) return items;
const data = items[0].json;
if (data.items && Array.isArray(data.items)) return data.items.map(item => ({ json: item }));
if (data.data && Array.isArray(data.data)) return data.data.map(item => ({ json: item }));
if (Array.isArray(data)) return data.map(item => ({ json: item }));
return items;

// Manual CSV Builder with Excel Magic
const cols = ['ID','Name','Email','Status','Score','Source','Last Interaction'];

function esc(v){
  if(v==null) return '';
  const s=String(v);
  // Escape quotes if needed
  return /[\",\n\r]/.test(s) ? '"' + s.replace(/"/g,'""') + '"' : s;
}

const rows = [cols.join(',')];

for (const { json:l } of items) {
  rows.push([
    l.id,
    l.name,
    l.email,
    l.status,
    l.score,
    l.source||'',
    l.lastInteraction||''
  ].map(esc).join(','));
}

// 1. Add BOM (\uFEFF) for UTF-8 support
// 2. Add 'sep=,' line so Excel knows to use commas
// 3. Join with CRLF (\r\n)
const csvContent = '\uFEFF' + ['sep=,', ...rows].join('\r\n');

return [{ json: { csv: csvContent } }];
